package main
import("database/sql";"fmt";"time";"os";_ "github.com/ory/lumen/internal/index")
func main(){d,e:=sql.Open("sqlite3",os.Args[1]);if e!=nil{panic(e)};defer d.Close();d.SetMaxOpenConns(1);for _,q:=range []string{"PRAGMA query_only=ON","PRAGMA foreign_keys=ON","PRAGMA cache_size=-64000","PRAGMA temp_store=MEMORY","PRAGMA busy_timeout=120000"}{if _,e=d.Exec(q);e!=nil{panic(e)}};var version string;d.QueryRow("select sqlite_version()").Scan(&version);fmt.Println("sqlite",version)
for _,join:=range []string{"project_files pf JOIN chunk_defs cd ON cd.file_revision_id=pf.file_revision_id JOIN file_revisions fr ON fr.id=pf.file_revision_id JOIN lexical_chunks ON lexical_chunks.rowid=cd.id","lexical_chunks CROSS JOIN chunk_defs cd ON lexical_chunks.rowid=cd.id CROSS JOIN project_files pf ON cd.file_revision_id=pf.file_revision_id CROSS JOIN file_revisions fr ON fr.id=pf.file_revision_id"}{q:=`SELECT pf.relative_path, cd.symbol, cd.kind, cd.start_line, cd.end_line, fr.content_hash, cd.references_json, cd.imports_json, cd.exported, bm25(lexical_chunks,12,16,6,3,1) - CASE WHEN lower(cd.symbol)=lower(?) THEN 1000 WHEN lower(pf.relative_path)=lower(?) THEN 500 ELSE 0 END AS score FROM `+join+` WHERE lexical_chunks MATCH ? AND pf.project_id=? ORDER BY score,pf.relative_path,cd.start_line,cd.id LIMIT ?`;a:=[]interface{}{"ValidateToken","ValidateToken",`"validatetoken" OR "validate" OR "token"`,2,9};fmt.Println("FROM",join);rows,e:=d.Query("EXPLAIN QUERY PLAN "+q,a...);if e!=nil{panic(e)};for rows.Next(){var id,parent,unused int;var desc string;rows.Scan(&id,&parent,&unused,&desc);fmt.Println(id,parent,desc)};rows.Close();for i:=0;i<3;i++{st:=time.Now();r,e:=d.Query(q,a...);if e!=nil{panic(e)};count:=0;for r.Next(){count++};e=r.Err();r.Close();if e!=nil{panic(e)};fmt.Println("query_ms",float64(time.Since(st).Nanoseconds())/1e6,"rows",count)}}}
